$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT EmployeeId, FullName, IsActive FROM Employees WHERE EmployeeId IN ('9080262','9106144','9124148','9074541','9074579','9074376')"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] '|' $r[1] '|' $r[2]}; $conn.Close(); Write-Host "---done---"
